CREATE TABLE IF NOT EXISTS cuentas (id BIGINT PRIMARY KEY AUTO_INCREMENT, titular VARCHAR(100) NOT NULL, saldo DECIMAL(19,2) NOT NULL, edad INT NOT NULL, tipo VARCHAR(30) NOT NULL, activa BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS movimientos (id BIGINT AUTO_INCREMENT PRIMARY KEY, cuenta_id BIGINT NOT NULL, fecha DATE NOT NULL, tipo VARCHAR(40) NOT NULL, monto DECIMAL(19,2) NOT NULL, descripcion VARCHAR(250), INDEX ix_mov_cuenta(cuenta_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS outbox_eventos (id VARCHAR(36) PRIMARY KEY, tipo VARCHAR(80) NOT NULL, cuenta_id BIGINT NOT NULL, monto DECIMAL(19,2) NOT NULL, saldo_resultante DECIMAL(19,2) NOT NULL, creado DATETIME NOT NULL, publicado BOOLEAN NOT NULL DEFAULT FALSE, INDEX ix_outbox_pendientes(publicado,creado)) ENGINE=InnoDB;
